<?php namespace Workspace; $id=(int)$project['id']; ?>
<div class="projectmeta"><span class="pill"><?= h(PROJECT_KINDS[$project['kind']]) ?></span><?php if ($project['client']): ?><span>Заказчик · <?= h($project['client']) ?></span><?php endif ?>
<?php if (roleAllows($projectRole,'finance')): ?><a href="<?= h(url('finance',['project'=>$id])) ?>">Финансы проекта</a><?php endif ?>
<?php if (roleAllows($projectRole,'legal')): ?><a href="<?= h(url('documents',['project'=>$id])) ?>">Документы проекта</a><?php endif ?></div>
<?php if (roleAllows($projectRole,'work')||roleAllows($projectRole,'finance')): ?><p><a class="secondary" href="<?= h(url('workload',['project'=>$id])) ?>">Спринты, загрузка и таймшиты</a></p><?php endif ?>
<?php if ($user['role']==='owner' && $project['kind']==='client'): ?><p><a href="<?= h(url('clients')) ?>">Клиенты и заказы</a></p><?php endif ?>
<?php require ROOT.'/views/planning.php'; ?>
<?php if (roleAllows($projectRole,'connections')): ?><section class="panel"><div class="panelhead"><h2>Подключения проекта</h2></div>
<?php if (!$links): ?><p class="empty">Подключения пока не привязаны.</p><?php endif ?>
<?php foreach ($links as $key): $c=$connections[$key] ?? null; ?><div class="splitrow"><div><b><?= h($c['label'] ?? $key) ?></b><small><?= h($c['status'] ?? 'Удалено из конфигурации') ?></small></div>
<?php if (!empty($c['launch'])): ?><a href="<?= h($c['launch']) ?>" target="_blank" rel="noopener noreferrer">Открыть</a><?php endif ?>
<?php if (roleAllows($projectRole,'operations')): ?><form method="post"><?php formFields('connection.detach') ?><input type="hidden" name="project_id" value="<?= $id ?>"><input type="hidden" name="connection" value="<?= h($key) ?>"><button class="secondary compact">Отвязать</button></form><?php endif ?></div><?php endforeach ?>
<?php if (roleAllows($projectRole,'operations') && ($other=array_diff_key($connections,array_flip($links)))): ?><form method="post" class="inline inset"><?php formFields('connection.attach') ?><input type="hidden" name="project_id" value="<?= $id ?>"><label>Подключение<select name="connection"><?php selectOptions(array_column($other,'label','id')) ?></select></label><button class="secondary">Привязать</button></form><?php endif ?></section><?php endif ?>
<?php if ($memberAdmin): ?><section class="panel"><div class="panelhead"><h2>Доступ к проекту</h2></div><p class="inset">Владельцы организации имеют административный доступ. Остальным требуется явное членство.</p>
<?php foreach ($members as $m): if ($m['role']!=='owner' && !in_array((int)$m['id'],$projectMembers,true)) continue; ?><div class="splitrow"><div><b><?= h($m['name']) ?></b><small><?= h($m['role']==='owner'?ROLES['owner']:PROJECT_ROLES[$explicitRoles[$m['id']]??'inherit'].' / '.ROLES[$m['role']]) ?><?= !$m['enabled']?' · отключён':'' ?></small></div><?php if ($user['role']==='owner' && $m['role']!=='owner'): ?><form method="post" class="inline"><?php formFields('project.role') ?><input type="hidden" name="project_id" value="<?= $id ?>"><input type="hidden" name="member_id" value="<?= h($m['id']) ?>"><label>Роль проекта<select name="role"><?php selectOptions(PROJECT_ROLES,$explicitRoles[$m['id']]??'inherit') ?></select></label><button class="secondary compact">Сохранить роль</button></form><?php endif ?><?php if ($m['role']!=='owner' && (int)$m['id']!==(int)$user['id'] && ($user['role']==='owner'||!isset($explicitRoles[$m['id']]))): ?><form method="post"><?php formFields('project.remove') ?><input type="hidden" name="project_id" value="<?= $id ?>"><input type="hidden" name="member_id" value="<?= h($m['id']) ?>"><button class="secondary compact">Закрыть доступ</button></form><?php endif ?></div><?php endforeach ?>
<?php $available=array_column(array_filter($members,fn($m)=>$m['enabled']&&$m['role']!=='owner'&&!in_array((int)$m['id'],$projectMembers,true)),'name','id'); if ($available): ?><form method="post" class="inline inset"><?php formFields('project.add') ?><input type="hidden" name="project_id" value="<?= $id ?>"><label>Участник<select name="member_id"><?php selectOptions($available) ?></select></label><button class="primary">Открыть доступ</button></form><?php endif ?></section><?php endif ?>

<?php if (roleAllows($projectRole,'audit')): ?><p><a href="<?= h(url('audit',['project'=>$id])) ?>">Аудит проекта</a></p><?php endif ?>
<?php if (roleAllows($projectRole,'finance')): ?><p><a href="<?= h(url('payments',['project'=>$id])) ?>">Заявки на платежи и сторно</a></p><?php endif ?>
<?php if ($user['role']==='owner'): ?><section class="panel inset"><h2>Согласование платежей</h2><p>При двойном контроле любая новая операция и сторно требуют решения другого уполномоченного участника. Уже созданные заявки сохраняют режим.</p><form method="post" class="inline"><?php formFields('payment.policy') ?><input type="hidden" name="project_id" value="<?= $id ?>"><label>Режим<select name="dual"><?php selectOptions(['0'=>'Прямое проведение','1'=>'Двойной контроль'],$dual?'1':'0') ?></select></label><button class="secondary">Сохранить режим</button></form></section><?php endif ?>
<?php if (isset($guestInvites)): ?><section class="panel inset"><h2>Гостевой кабинет клиента</h2><p>Код действует до указанного срока и принимается один раз. После входа клиент видит только название проекта и выбранную редакцию PDF (30 дней или до отзыва).</p>
<?php if (!empty($guestToken)): ?><p>Передайте клиенту код по защищённому каналу: <input aria-label="Код клиента" readonly value="<?= h($guestToken) ?>"></p><p>Адрес кабинета: <a href="<?= h(url('guest.join')) ?>"><?= h(url('guest.join')) ?></a></p><?php endif ?>
<?php if (oidcEnabled() && $guestVersions): ?><form method="post" class="formgrid"><?php formFields('guest.issue') ?><input type="hidden" name="project_id" value="<?= $id ?>"><label>Почта клиента<input name="email" type="email" required></label><label>Редакция<select name="version"><?php foreach ($guestVersions as $v): ?><option value="<?= h($v['id'].':'.$v['revision']) ?>"><?= h($v['title'].' — v'.$v['revision']) ?></option><?php endforeach ?></select></label><label>Срок кода, часов<input name="hours" type="number" min="1" max="168" value="24" required></label><button class="primary">Создать приглашение</button></form><?php else: ?><p>Для приглашения настройте OIDC и загрузите редакцию PDF.</p><?php endif ?>
<?php foreach ($guestInvites as $g): ?><div class="splitrow"><div><b><?= h($g['email']) ?></b><small>PDF #<?= h($g['document_id']) ?> v<?= h($g['revision']) ?> · <?= $g['revoked_at']?'отозвано':($g['accepted_at']?($g['access_until']>time()?'принято':'доступ истёк'):($g['expires_at']>time()?'ожидает':'код истёк')) ?></small></div><?php if (!$g['revoked_at']): ?><form method="post"><?php formFields('guest.revoke') ?><input type="hidden" name="project_id" value="<?= $id ?>"><input type="hidden" name="guest_id" value="<?= h($g['id']) ?>"><button class="secondary">Отозвать</button></form><?php endif ?></div><?php endforeach ?></section><?php endif ?>
